import "array"
import "date"
import "regexp"
// Same target matching as the panels: any probe of this base name.
base = regexp.replaceAllString(r: /(_h[123]|_tcp(443)?|_icmp)$/, v: "${target}", t: "")
re = regexp.compile(v: "^(?i)" + regexp.quoteMeta(v: base) + "(_h[123]|_tcp(443)?|_icmp)?$")
// A period is stamped at its start: reach back so one that began before
// the range but ends inside it is still shaded.
// coverage: the share of the period's 15-minute bins with an answered ping (a gap of hours,
// a hang or a reboot, reads below 1); ks_p: the KS test's p-value, the evidence that the
// latency distribution changed (store.py).
// A target the exporter tagged as a multi-tenant CDN (target_labels, field kind, its last
// point: docs/taxonomy.md) answers from whichever edge the CDN's routing (anycast) or DNS
// picks, and a farther edge raises the floor just as a queue would: say so, keep the shade
// (docs/inference.md#anycast-destinations). An empty name pads the list, so it is never
// empty: no target is named "".
cdn = from(bucket: "smokeping") |> range(start: 0)
  |> filter(fn: (r) => r._measurement == "target_labels" and r.target =~ re and r._field == "kind")
  |> last() |> filter(fn: (r) => r._value == "cdn") |> group() |> keep(columns: ["target"])
edge = union(tables: [cdn, array.from(rows: [{target: ""}])]) |> group()
  |> findColumn(fn: (key) => true, column: "target")
from(bucket: "smokeping") |> range(start: date.sub(d: 14d, from: v.timeRangeStart), stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "persistent_congestion" and r.target =~ re and (r._field == "end" or r._field == "confidence" or r._field == "jump_ms" or r._field == "coverage" or r._field == "ks_p" or r._field == "triage"))
  |> pivot(rowKey: ["_time", "target"], columnKey: ["_field"], valueColumn: "_value")
  |> filter(fn: (r) => r.end * 1000000000 >= int(v: v.timeRangeStart))
  |> map(fn: (r) => ({_time: r._time, timeEnd: time(v: r.end * 1000000000), text: "Persistent congestion (Jitterbug, experimental) on " + r.target + (if contains(value: r.target, set: edge) then ", edge change likely (anycast/CDN destination): " + r.target + " answers from a CDN edge, and a farther edge raises the floor just as a queue would. The minimum RTT rose " else ": the minimum RTT rose ") + (if exists r.jump_ms then string(v: float(v: int(v: r.jump_ms * 10.0)) / 10.0) else "?") + " ms and stayed; confidence " + (if exists r.confidence then string(v: float(v: int(v: r.confidence * 100.0)) / 100.0) else "?") + (if exists r.coverage then ", coverage " + string(v: float(v: int(v: r.coverage * 100.0 + 0.5)) / 100.0) else "") + (if not exists r.ks_p then "" else if r.ks_p < 0.001 then ", KS p < 0.001" else ", KS p " + string(v: float(v: int(v: r.ks_p * 1000.0 + 0.5)) / 1000.0)) + (if exists r.triage then ". Layers: " + r.triage else ""), tags: "experimental"}))

import "date"
import "regexp"
// Same target matching as the panels: any probe of this base name.
base = regexp.replaceAllString(r: /(_h[123]|_tcp(443)?|_icmp)$/, v: "${target}", t: "")
re = regexp.compile(v: "^(?i)" + regexp.quoteMeta(v: base) + "(_h[123]|_tcp(443)?|_icmp)?$")
// The peak's clock time, always in UTC and said so: a time zone the query could not resolve would fail the whole annotation.
two = (n) => if n < 10 then "0" + string(v: n) else string(v: n)
clock = (t) => two(n: date.hour(t: t)) + ":" + two(n: date.minute(t: t)) + " UTC"
pct = (x) => string(v: float(v: int(v: x * 10.0 + 0.5)) / 10.0)
span = (s) => if s < 7200 then string(v: s / 60) + " min" else string(v: float(v: s / 360) / 10.0) + " h"
// A period is stamped at its start: reach back so one that began before
// the range but ends inside it is still shaded.
from(bucket: "smokeping") |> range(start: date.sub(d: 14d, from: v.timeRangeStart), stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "loss_degradation" and r.target =~ re and (r._field == "end" or r._field == "mean_loss_pct" or r._field == "class" or r._field == "coverage" or r._field == "burst" or r._field == "peak_pct" or r._field == "peak_start" or r._field == "triage"))
  |> pivot(rowKey: ["_time", "target"], columnKey: ["_field"], valueColumn: "_value")
  |> filter(fn: (r) => r.end * 1000000000 >= int(v: v.timeRangeStart))
  // Periods written before the class existed have none: they are loss.
  |> filter(fn: (r) => not exists r.class or r.class != "monitor_deaf")
  // A burst (all of the period's loss in one 15-minute bin) is shaded over that bin, not over BCP's segment:
  // the segment's mean pools the bin with clean ones (one bin at 31 % in 14 reads as 3.5 h at 2.2 %).
  // Periods written before the burst fields existed have none: they read as before.
  |> map(fn: (r) => {
      burst = exists r.burst and r.burst == 1 and exists r.peak_start and exists r.peak_pct
      avg = if exists r.mean_loss_pct then pct(x: r.mean_loss_pct) else "?"
      seg = span(s: r.end - int(v: r._time) / 1000000000)
      // Which other layers moved with the period (triage.py), when the pass that wrote it read them.
      layers = if exists r.triage then ". Layers: " + r.triage else ""
      return {_time: if burst then time(v: r.peak_start * 1000000000) else r._time,
        timeEnd: if burst then time(v: (r.peak_start + 900) * 1000000000) else time(v: r.end * 1000000000),
        text: if burst then "Loss burst (experimental) on " + r.target + ": 15 min at " + pct(x: r.peak_pct) + " % (inside a " + seg + " segment averaging " + avg + " %)" + layers
          else ("Loss degradation (experimental) on " + r.target + ": " + avg + " % mean loss" + (if exists r.peak_pct and exists r.peak_start then ", peak " + pct(x: r.peak_pct) + " % at " + clock(t: time(v: r.peak_start * 1000000000)) else "") + (if exists r.coverage then ", data in " + string(v: int(v: r.coverage * 100.0)) + " % of the span" else "")) + layers,
        tags: "experimental"}
  })

