import "date"
// The whole connection's loss periods (shared.py): one detector run on every destination's
// loss together. shared_degradation has no target tag: the period is the house's, drawn on
// every target so that this target's own loss is read inside it (or outside it).
pct = (x) => string(v: float(v: int(v: x * 10.0 + 0.5)) / 10.0)
// A period is stamped at its start: reach back so one that began before
// the range but ends inside it is still shaded.
from(bucket: "smokeping") |> range(start: date.sub(d: 14d, from: v.timeRangeStart), stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "shared_degradation" and (r._field == "end" or r._field == "mean_loss_pct" or r._field == "voters" or r._field == "scope" or r._field == "dominant"))
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> filter(fn: (r) => r.end * 1000000000 >= int(v: v.timeRangeStart))
  // scope is "shared" when a third of the operators behind the targets lost and they are of two
  // kinds of infrastructure or more; "dominated" when one destination (dominant) carried it.
  |> map(fn: (r) => ({_time: r._time, timeEnd: time(v: r.end * 1000000000), text: "Whole connection lost " + (if exists r.mean_loss_pct then pct(x: r.mean_loss_pct) else "?") + " % (" + (if exists r.voters then string(v: r.voters) else "?") + " voters, scope " + (if not exists r.scope then "?" else if r.scope == "shared" then "shared across operators" else "one destination" + (if exists r.dominant and r.dominant != "" then ", " + r.dominant else "")) + "; experimental): the house's period, every destination's loss together, not this target's. Who lost: Connectivity & Quality, same range (link above).", tags: "experimental,whole-connection"}))

