import "regexp"
import "strings"
// Any name a link brings (Google, Google_h2, cloudflare) selects the whole target:
// drop the probe suffix, then match every probe of that base name, any case.
base = regexp.replaceAllString(r: /(_h[123]|_tcp(443)?|_icmp)$/, v: "${target}", t: "")
re = regexp.compile(v: "^(?i)" + regexp.quoteMeta(v: base) + "(_h[123]|_tcp(443)?|_icmp)?$")
// The newest point any probe of this target wrote inside the range, as its age now;
// the point's own time travels as the field name, which the tile shows under the age.
from(bucket:"smokeping") |> range(start:v.timeRangeStart, stop:v.timeRangeStop)
  |> filter(fn:(r)=> (r._measurement == "latency" or r._measurement == "tcp_latency" or r._measurement == "http_latency" or r._measurement == "dns_latency") and r.target =~ re and r._field == "loss")
  |> last() |> keep(columns:["_time"]) |> group() |> sort(columns:["_time"], desc:true) |> limit(n:1)
  |> map(fn:(r)=> ({_time: r._time, _value: float(v: int(v: now()) - int(v: r._time)) / 1000000000.0, _field: "newest point " + strings.replace(v: strings.substring(v: string(v: r._time), start: 0, end: 16), t: "T", u: " ", i: 1) + " UTC"}))
  |> keep(columns:["_time","_value","_field"]) |> group(columns:["_field"])

import "internal/debug"
// Minutes inside the range in which this Pi's own radio heard nothing, from the Wi-Fi
// collector's samples: the deaf definition of common/microcuts.uplink_flux (the alerter,
// the doctor's monitor-radio check and the inference service's deaf.py read the same),
// restated here because a dashboard cannot import it; a test holds the two equal. A
// sample counts while its interface carries the default route; it is deaf when the
// received-packet counter did not move since the sample before, or the radio is not
// associated. Not the monitor_deaf periods: one of those spans every bin BCP put in it,
// clean hours included, and the alerter's local_wifi incidents are diagnosed from these
// same samples (adding their spans would count a deaf minute twice).
from(bucket: "smokeping") |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "wifi_link")
  |> filter(fn: (r) => r._field == "rx_packets" or r._field == "associated" or r._field == "uplink") |> keep(columns: ["_time", "_field", "_value", "interface"]) |> group(columns: ["interface"]) |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value") |> sort(columns: ["_time"]) |> map(fn: (r) => ({r with uplink: if r.associated == 0 then debug.null(type: "int") else r.uplink})) |> fill(column: "uplink", usePrevious: true) |> difference(columns: ["rx_packets"]) 
  // Each deaf sample speaks for the time since its interface's sample before (10 s at the
  // collector's default interval), up to a minute: a longer gap is the collector not
  // sampling (a reboot, a stop), not a minute heard as silent.
  |> elapsed(unit: 1s)
  |> filter(fn: (r) => r.uplink == 1 and (r.rx_packets == 0 or r.associated == 0)) 
  |> map(fn: (r) => ({_time: r._time, _value: float(v: if r.elapsed < 60 then r.elapsed else 60) / 60.0}))
  |> group() |> sum()
  |> set(key: "_field", value: "deaf") |> keep(columns: ["_value", "_field"]) |> group(columns: ["_field"])

