  |> last()
  |> pivot(rowKey:["_time","target"], columnKey:["_field"], valueColumn:"_value")
  |> group()
  |> map(fn:(r)=> ({r with rank: if strings.toLower(v: r.target) == strings.toLower(v: base) then 0 else 1}))
  |> sort(columns:["rank","target"]) |> limit(n:1)
// The service's name is what a person reads: it is the value; its categories (or
// "unknown (no rule yet)") travel as the field name, the small text over it.
row
  |> map(fn:(r)=> ({_field: if not exists r.categories then "unknown (no rule yet)" else if r.categories == "unknown" or r.categories == "" then "unknown (no rule yet)" else strings.replaceAll(v: r.categories, t: ",", u: ", "), _value: if exists r.service and r.service != "" then r.service else r.target}))
  |> keep(columns:["_value","_field"]) |> group(columns:["_field"])

