import "regexp"
// pathmeter stores one path per base name (docs/path.md): match that name, any case.
base = regexp.replaceAllString(r: /(_h[123]|_tcp(443)?|_icmp)$/, v: "${target}", t: "")
re = regexp.compile(v: "^(?i)" + regexp.quoteMeta(v: base) + "$")
// The last trace in the selected range, and its hops (one timestamp per cycle).
latest = from(bucket: "smokeping") |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "path_trace" and r._field == "hops" and r.target =~ re)
  |> last() |> group() |> sort(columns: ["_time"], desc: true) |> findRecord(fn: (key) => true, idx: 0)
at = if exists latest._time then latest._time else time(v: 0)
private = /^(10\.|127\.|169\.254\.|192\.168\.|172\.(1[6-9]|2[0-9]|3[01])\.|100\.(6[4-9]|[7-9][0-9]|1[01][0-9]|12[0-7])\.|(?i)f[cd]|(?i)fe[89ab])/
from(bucket: "smokeping") |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "path_hop" and r.target =~ re and r._time == at
    and (r._field == "addr" or r._field == "asn" or r._field == "ixp" or r._field == "ptr" or r._field == "rtt_ms"))
  |> pivot(rowKey: ["_time", "ttl"], columnKey: ["_field"], valueColumn: "_value")
  |> group()
// net: which color the row takes. One per AS, the AS number modulo the 12 colors,
// so an AS has the same color on every target; "private" (gray) when the hop has
// no AS or a non-public address (RFC 1918, CGNAT 100.64/10, IPv4 loopback, link-local, ULA).
  |> map(fn: (r) => ({r with net: if not exists r.asn or regexp.matchRegexpString(r: private, v: r.addr) then "private" else string(v: r.asn % 12)}))
  |> keep(columns: ["ttl", "addr", "ptr", "asn", "ixp", "rtt_ms", "net"]) |> sort(columns: ["ttl"])
